package com.project7.localmanager;
import android.content.*;import android.content.res.*;import android.system.Os;import java.io.*;import java.nio.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
/** Actual stock Store/granter/consumer frames; synthetic inventory only. */
public final class BaiyeHost {
 static final String ACCOUNT="host_baiye_synthetic";static final byte[]EID=new byte[12];
 static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 static byte[]item(int id,int n){return BsonLite.document("i",id,"w",n,"u",new BsonLite.UuidValue(LocalResourceEngine.uuid()),"host_unknown","keep");}
 static byte[]profile(int source,int target){List<byte[]>items=new ArrayList<>();if(source>0)items.add(item(10313,source));if(target>0)items.add(item(10314,target));return BsonLite.document("account",ACCOUNT,"an",ACCOUNT,"st",900999,"inv",BsonLite.document("items",items,"opaque","preserve"),"unknown","preserve");}
 static final class Disk implements AutoCloseable {
  final Path root;final File file;final LocalProfileStore store;final LocalGatewayServer g;
  Disk(File assets,byte[]p)throws Exception{root=Files.createTempDirectory("baiye-synthetic-");Files.createDirectory(root.resolve("profiles"));file=root.resolve("profiles/"+ACCOUNT+".bson").toFile();Files.write(file.toPath(),p);store=new LocalProfileStore(new Context(root.toFile(),new AssetManager(assets)));g=new LocalGatewayServer(0,null,store,null,null,null,null,null,null);}
  byte[]read()throws Exception{return Files.readAllBytes(file.toPath());}
  public void close()throws Exception{g.close();try(java.util.stream.Stream<Path>s=Files.walk(root)){for(Path p:(Iterable<Path>)s.sorted(Comparator.reverseOrder())::iterator)Files.delete(p);}}
  List<ProtoLite.EntityMessage>direct(byte[]params)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();check(BaiyeGateway.handleDirect(g,out,EID,BaiyeGateway.digest("commonItemFusionAsk"),params,ACCOUNT,null,null),"handled");return frames(out.toByteArray());}
 }
 static List<ProtoLite.EntityMessage>frames(byte[]wire)throws Exception{List<ProtoLite.EntityMessage>r=new ArrayList<>();ByteBuffer b=ByteBuffer.wrap(wire).order(ByteOrder.LITTLE_ENDIAN);while(b.hasRemaining()){int len=b.getInt();check(b.getShort()==5,"opcode5");byte[]msg=new byte[len-2];b.get(msg);r.add(ProtoLite.parseEntityMessage(msg));}return r;}
 static byte[]params(int n){return BsonLite.document("i",10313,"f",10314,"n",n,"_cbid_",7);}
 static ProtoLite.EntityMessage reply(List<ProtoLite.EntityMessage>r){for(ProtoLite.EntityMessage m:r)if(Arrays.equals(m.methodMd5,BaiyeGateway.digest("commonItemFusionReply")))return m;throw new AssertionError("fusion reply");}
 static void callback(List<ProtoLite.EntityMessage>r){int count=0;for(ProtoLite.EntityMessage m:r)if(Arrays.equals(m.methodMd5,BaiyeGateway.digest("serverCallbackCarrier")))count++;check(count==1&&Arrays.equals(r.get(r.size()-1).methodMd5,BaiyeGateway.digest("serverCallbackCarrier")),"one last original callback");}
 static void negative(Disk d,byte[]params)throws Exception{byte[]before=d.read();List<ProtoLite.EntityMessage>r=d.direct(params);check(BsonLite.keys(BsonLite.documentValue(reply(r).parameters,"r")).isEmpty(),"negative empty reward");check(Arrays.equals(before,d.read()),"negative no mutation");}
 public static void main(String[]args)throws Exception{
  File assets=new File(args[0]);Context c=new Context(assets,new AssetManager(assets));CoreDrawPolicy.prepare(c);HistoryDrawPolicy.prepare(c);SelectorPolicy.prepare(c);OfflineMechanismGateway.prepare(c);BaiyeGateway.prepare(c);Map<String,Object>consumer=new LinkedHashMap<>();
  try(Disk d=new Disk(assets,profile(12,0))){int writes=Os.renames;List<ProtoLite.EntityMessage>r=d.direct(params(2));callback(r);check(BaiyeTransactions.count(d.read(),10313)==4&&BaiyeTransactions.count(d.read(),10314)==2,"real 4:1 output count");check(Os.renames==writes+1,"single stock atomic write");check("preserve".equals(BsonLite.stringValue(d.read(),"unknown")),"unknown preserved");consumer.put("success",BsonLite.messagePackValue(reply(r).parameters,false));consumer.put("callback",BsonLite.messagePackValue(r.get(r.size()-1).parameters,false));consumer.put("failure",BsonLite.messagePackValue(BaiyeGateway.failure("fixture").replies.get(1).parameters,false));
   callback(d.direct(params(1)));check(BaiyeTransactions.count(d.read(),10314)==3,"second legal same operation consumes again, no parameter hash dedupe");
   negative(d,params(1));negative(d,params(0));negative(d,BsonLite.document("i",10313,"f",10315,"n",1));negative(d,BsonLite.document("i",10313,"f",10314,"n",Integer.MAX_VALUE));
  }
  try(Disk d=new Disk(assets,profile(8,0))){byte[]before=d.read();Os.failBefore=true;negative(d,params(1));check(Arrays.equals(before,d.read()),"precommit no changes");Os.failAfter=true;callback(d.direct(params(1)));check(BaiyeTransactions.count(d.read(),10314)==1,"rename then throw recognized committed not negative");
   byte[]committed=d.read();OutputStream broken=new OutputStream(){public void write(int b)throws IOException{throw new IOException("host disconnect");}};try{BaiyeGateway.handleDirect(d.g,broken,EID,BaiyeGateway.digest("commonItemFusionAsk"),params(1),ACCOUNT,null,null);throw new AssertionError("disconnect");}catch(IOException expected){}check(!Arrays.equals(committed,d.read())&&BaiyeTransactions.count(d.read(),10314)==2,"postcommit wire failure remains committed no fake negative");
  }
  for(int[]rule:new int[][]{{10314,10315},{10315,10316}}){byte[]p=BsonLite.document("account",ACCOUNT,"an",ACCOUNT,"inv",BsonLite.document("items",Arrays.asList(item(rule[0],8))));try(Disk d=new Disk(assets,p)){LocalResourceEngine.Result r=BaiyeTransactions.fusion(d.store,ACCOUNT,rule[0],rule[1],2);check(BaiyeTransactions.count(d.read(),rule[0])==0&&BaiyeTransactions.count(d.read(),rule[1])==2,"all fixed fusion rules");}}
  try(Disk d=new Disk(assets,profile(8,0))){callback(d.direct(params(1)));callback(d.direct(params(1)));check(BaiyeTransactions.count(d.read(),10314)==2,"identical ordinary params are two real transactions");}
  try(Disk d=new Disk(assets,profile(8,0))){Os.afterRename=(name)->{Os.afterRename=null;throw new IllegalStateException("fixture postrename runtime");};callback(d.direct(params(1)));check(BaiyeTransactions.count(d.read(),10314)==1,"runtime postrename exact image recognized committed");}
  try(Disk d=new Disk(assets,profile(8,0))){byte[]third=profile(1,7);Os.afterRename=(name)->{Os.afterRename=null;try{Files.write(d.file.toPath(),third);}catch(IOException x){throw new RuntimeException(x);}throw new IllegalStateException("fixture uncertain image");};try{d.direct(params(1));throw new AssertionError("uncertain image must disconnect");}catch(BaiyeTransactions.UncertainCommit expected){}check(Arrays.equals(third,d.read()),"unknown commit never overwrites disk or invents negative");}
  try(Disk d=new Disk(assets,profile(8,0))){negative(d,BsonLite.document("i",10313,"f",10314,"n",1,"unknown",true));negative(d,BsonLite.document("i",10313,"f",10314,"n",1.0));negative(d,BsonLite.document("i",10313,"i",10313,"f",10314,"n",1));}
  try(Disk d=new Disk(assets,profile(4,Integer.MAX_VALUE))){negative(d,params(1));}
  try(Disk d=new Disk(assets,profile(4,0))){byte[]before=d.read();ByteArrayOutputStream out=new ByteArrayOutputStream();check(!BaiyeGateway.handleDirect(d.g,out,EID,BaiyeGateway.digest("buyCardMallItem"),params(1),ACCOUNT,null,null),"stock route untouched");check(BaiyeGateway.handleRequest(d.g,out,EID,"commonItemFusionAsk",params(1),7,ACCOUNT,null,null),"reliable typed rejection");check(Arrays.equals(before,d.read()),"reliable no charging");callback(frames(out.toByteArray()));}
  try(Disk d=new Disk(assets,profile(4,0))){ExecutorService pool=Executors.newFixedThreadPool(2);try{List<Future<Boolean>>jobs=new ArrayList<>();for(int i=0;i<2;i++)jobs.add(pool.submit(()->{try{BaiyeTransactions.fusion(d.store,ACCOUNT,10313,10314,1);return true;}catch(IllegalArgumentException x){return false;}}));int accepted=0;for(Future<Boolean>j:jobs)if(j.get())accepted++;check(accepted==1&&BaiyeTransactions.count(d.read(),10314)==1,"concurrent cannot overspend");}finally{pool.shutdownNow();}}
  Files.write(Paths.get(args[1]),new org.json.JSONObject(consumer).toString(2).getBytes("UTF-8"));System.out.println("PASS original Store fusion4:1, actual consume/grant/replies, repeated/concurrent/overflow/failure/aftercommit/reliable-negative");
 }
}
